import { setTimeout as sleep } from 'node:timers/promises';
import { confirm } from '@inquirer/prompts';
import { patchLocatedConfig } from '../../actions/blueprints/config.js';
import { destroyStack, getStack, resolveStackIdByNameOrId } from '../../actions/blueprints/stacks.js';
import { waitForOperation } from '../../actions/blueprints/wait-for-operation.js';
import { niceId } from '../../utils/display/presenters.js';
import { CODE_OPERATION_UNCONFIRMED, EXIT_OPERATION_UNCONFIRMED } from '../../utils/exit-codes.js';
import { runCommand } from '../../utils/package-manager.js';
import { styleText } from '../../utils/style-text.js';
import { createTracedFetch } from '../../utils/traced-fetch.js';
export async function blueprintDestroyCore(options) {
    const { bin = 'sanity', log, token, scopeType, scopeId, localStackId, blueprintConfig, flags, } = options;
    const { force = false, 'project-id': flagProjectId, 'organization-id': flagOrganizationId, stack: flagStack, 'no-wait': noWait = false, verbose = false, } = flags;
    // 3-flag combo: non-interactive destroy that does not need a local Blueprint nearby.
    // Scope comes from the --project-id/--organization-id flags (resolved by the base command).
    if ((flagProjectId || flagOrganizationId) && flagStack && force) {
        if (!scopeType || !scopeId) {
            return { success: false, error: 'Unable to determine scope for Blueprint Destroy' };
        }
        const auth = { token, scopeType, scopeId };
        const resolvedId = await resolveStackIdByNameOrId(flagStack, auth, log);
        const { ok, error, stack, requestId } = await destroyStack({
            stackId: resolvedId,
            auth,
            logger: log,
        });
        if (!ok) {
            return { success: false, error: error || 'Failed to destroy Stack deployment', requestId };
        }
        clearLocalStackIdFromConfig(blueprintConfig, stack.id, log);
        return afterDestroyAccepted({
            stackId: stack.id,
            stackName: stack.name,
            operationId: stack.operationId,
            requestId,
            noWait,
            auth,
            log,
            bin,
            verbose,
        });
    }
    if (!scopeType || !scopeId)
        return { success: false, error: 'Scope is required' };
    const auth = { token, scopeType, scopeId };
    const resolvedStackId = flagStack
        ? await resolveStackIdByNameOrId(flagStack, auth, log)
        : undefined;
    let stack;
    try {
        const fetchFn = createTracedFetch(log);
        if (resolvedStackId) {
            const overrideStack = await getStack({ stackId: resolvedStackId, auth, fetchFn });
            if (!overrideStack.ok)
                return { success: false, error: overrideStack.error || 'Failed to get Stack' };
            stack = overrideStack.stack;
        }
        else if (localStackId) {
            const blueprintStack = await getStack({ stackId: localStackId, auth, fetchFn });
            if (!blueprintStack.ok)
                return { success: false, error: blueprintStack.error || 'Failed to get Stack' };
            stack = blueprintStack.stack;
        }
        if (!stack) {
            return {
                success: false,
                error: 'Stack deployment not found',
                suggestions: [
                    `Run \`${runCommand(bin)} blueprints stacks\` to list available Stacks.`,
                    `Run \`${runCommand(bin)} blueprints doctor\` to check your configuration.`,
                ],
            };
        }
        const destroySpinner = log.ora({
            text: `Destroying Stack deployment "${styleText('bold', stack.name)}" ${niceId(stack.id)}...`,
            color: 'red',
        });
        if (!force) {
            const confirmed = await confirm({
                message: `Are you sure you want to destroy stack "${stack.name}" ${niceId(stack.id)}?`,
                default: false,
            });
            if (!confirmed) {
                log('Stack deployment destruction cancelled');
                return { success: true };
            }
            destroySpinner.start();
            // 5 second countdown
            let i = 5;
            while (i >= 0) {
                destroySpinner.text = `Destroying Stack deployment in ${styleText('bold', (i--).toString())} seconds...`;
                await sleep(1000);
            }
            destroySpinner.text = 'Destroying Stack deployment 💥';
            await sleep(500);
        }
        else {
            destroySpinner.start();
        }
        const { ok, error, stack: destroyedStack, requestId, } = await destroyStack({
            stackId: stack.id,
            auth,
            logger: log,
        });
        if (!ok) {
            destroySpinner.fail('Failed to destroy Stack deployment');
            return { success: false, error: error || 'Failed to destroy Stack deployment', requestId };
        }
        destroySpinner.stop().clear();
        clearLocalStackIdFromConfig(blueprintConfig, stack.id, log);
        return afterDestroyAccepted({
            stackId: stack.id,
            stackName: stack.name,
            operationId: destroyedStack.operationId,
            requestId,
            noWait,
            auth,
            log,
            bin,
            verbose,
        });
    }
    catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        return { success: false, error: errorMessage };
    }
}
function clearLocalStackIdFromConfig(blueprintConfig, destroyedStackId, log) {
    if (!blueprintConfig)
        return;
    if (blueprintConfig.stackId !== destroyedStackId)
        return;
    try {
        patchLocatedConfig(blueprintConfig, { stackId: null });
        log(styleText('dim', 'Removed stackId from .sanity/blueprint.config.json'));
    }
    catch {
        log(styleText('yellow', 'Could not update .sanity/blueprint.config.json. Remove stackId manually.'));
    }
}
function afterDestroyAccepted(options) {
    const { stackId, stackName, requestId, noWait, log, verbose = false } = options;
    if (requestId)
        log.verbose(styleText('dim', `Request ID: ${requestId}`));
    if (noWait) {
        log(styleText(['bold', 'magenta'], 'Stack destruction started!'));
        if (requestId && !verbose)
            log(styleText('dim', `Request ID: ${requestId}`));
        return { success: true, json: { stackId, stackName, requestId } };
    }
    return waitForDestruction(options);
}
async function waitForDestruction(options) {
    const { stackId, stackName, operationId, requestId, auth, log, bin, verbose = false } = options;
    log(styleText('dim', 'Stack destruction progress:'));
    log('');
    const outcome = await waitForOperation({
        stackId,
        operationId,
        auth,
        log,
        bin,
        verbose,
        includeDestroyed: true,
        progressNoun: 'destruction',
    });
    if (outcome.type === 'completed') {
        log(styleText(['bold', 'magenta'], 'Stack destruction completed!'));
        return { success: true, json: { stackId, stackName, requestId } };
    }
    if (outcome.type === 'unconfirmed') {
        return {
            success: false,
            error: `Stack destruction was accepted but completion could not be confirmed${outcome.error ? ` (${outcome.error})` : ''}.`,
            requestId,
            code: CODE_OPERATION_UNCONFIRMED,
            exitCode: EXIT_OPERATION_UNCONFIRMED,
            suggestions: [
                'The destruction may or may not have finished on Sanity servers.',
                `Run \`${runCommand(bin)} blueprints info\` to view current Stack status.`,
                `Run \`${runCommand(bin)} blueprints logs --watch\` to keep streaming logs.`,
            ],
        };
    }
    return {
        success: false,
        error: 'Stack destruction failed',
        requestId,
        suggestions: [
            ...outcome.logHints,
            'Review the destruction output above for error details.',
            `Run \`${runCommand(bin)} blueprints logs --verbose\` for more context.`,
            `Run \`${runCommand(bin)} blueprints info\` to view current Stack status.`,
        ],
    };
}
